const RULES={fire:5,seed1:5,seed2:10,seed3:15,flag:20,flagBoost:40,partial:5,full:10,allianceBonus:10,wrong:-3,penalty:-5,yellow:-10};
const STORE='fanroc-score-v1';
const initial={settings:{tournament:'FAnRoC 2026',roundsPerTeam:4,roundName:'Vòng xếp hạng',teamPrefix:'F'},teams:[],matches:[],nextTeam:1,nextMatch:1,selectedMatch:null,projectedMatch:null};
let db=load();let activeView='dashboard',scoreTab='balls',toastTimer;
function load(){try{return {...structuredClone(initial),...JSON.parse(localStorage.getItem(STORE)||'{}')}}catch{return structuredClone(initial)}}
function save(){localStorage.setItem(STORE,JSON.stringify(db));updateCloud()}
function updateCloud(){const s=document.querySelector('#cloudStatus span');if(s)s.textContent='Chế độ thử nghiệm · lưu trên thiết bị này'}
function uid(prefix){return prefix+'-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,6)}
function notify(s){const el=document.querySelector('#toast');el.textContent=s;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
function fmt(n){return Number(n||0).toLocaleString('vi-VN')}
function teamName(id){return db.teams.find(t=>t.id===id)?.name||'Chưa gán đội'}
function getMatch(id=db.selectedMatch){return db.matches.find(m=>m.id===id)}
function totalCounts(m){return Object.values(m.score?.mountains||{}).reduce((a,x)=>({seed1:a.seed1+(+x.seed1||0)+(+x.decor||0),seed2:a.seed2+(+x.seed2||0),seed3:a.seed3+(+x.seed3||0),wrong:a.wrong+(+x.wrong||0)}),{seed1:0,seed2:0,seed3:0,wrong:0})}
function calc(m){if(!m)return {components:{},matchTotal:0,teams:[]};let s=m.score||{},mountains=s.mountains||{};const fire=(+s.fire||0)*RULES.fire;let seeds={seed1:0,seed2:0,seed3:0},flags=0,wrong=+s.wrongGreen||0;
Object.values(mountains).forEach(x=>{seeds.seed1+=((+x.seed1||0)+(+x.decor||0))*RULES.seed1;seeds.seed2+=(+x.seed2||0)*RULES.seed2;seeds.seed3+=(+x.seed3||0)*RULES.seed3;wrong+=(+x.wrong||0);if(x.flag){let covered=(+x.seed1||0)+(+x.decor||0)>0&&(+x.seed2||0)>0&&(+x.seed3||0)>0;flags+=covered?RULES.flagBoost:RULES.flag}});
let robot=s.robots||{},robotPts=0,alliancePts=0;['red','blue'].forEach(color=>{let ids=m.alliances?.[color]||[];let fully=ids.filter(id=>robot[id]==='full');ids.forEach(id=>{if(robot[id]==='full')robotPts+=RULES.full;else if(robot[id]==='partial')robotPts+=RULES.partial});if(ids.length===2&&fully.length===2)alliancePts+=RULES.allianceBonus});
let wrongPts=wrong*RULES.wrong;let matchTotal=fire+seeds.seed1+seeds.seed2+seeds.seed3+flags+robotPts+alliancePts+wrongPts;
const teams=m.teams.map(id=>{let events=(m.penalties||[]).filter(x=>x.teamId===id);let p=events.filter(x=>x.type==='penalty').reduce((n,x)=>n+x.count,0);let y=events.filter(x=>x.type==='yellow').reduce((n,x)=>n+x.count,0);let red=events.some(x=>x.type==='red')||y>=2;let personal=Math.max(0,matchTotal-p*5-y*10);return {id,total:red?0:personal,red,p,y,penaltyPoints:p*5+y*10}});
return {components:{fire,seeds,flags,robotPts,alliancePts,wrongPts},matchTotal,teams}}
function attachScore(m){m.score=m.score||{fire:0,mountains:{A:{seed1:0,decor:0,seed2:0,seed3:0,wrong:0,flag:false},B:{seed1:0,decor:0,seed2:0,seed3:0,wrong:0,flag:false},C:{seed1:0,decor:0,seed2:0,seed3:0,wrong:0,flag:false},D:{seed1:0,decor:0,seed2:0,seed3:0,wrong:0,flag:false}},robots:{},penalties:[],notes:'',status:'draft'};m.penalties=m.penalties||[];m.alliances=m.alliances||{red:[],blue:[]};return m}
function statusTag(m){let a={scheduled:['Chưa đấu','gray'],live:['Đang đấu','green'],review:['Chờ xác nhận','yellow'],published:['Đã công bố','blue'],locked:['Đã khóa','gray']}[m.status]||['Chưa đấu','gray'];return `<span class="tag ${a[1]}">${a[0]}</span>`}
function pageHead(eyebrow,title,sub,actions=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="row">${actions}</div></div>`}
function cardTitle(title,sub='',right=''){return `<div class="section-title"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`}
function nav(){document.querySelectorAll('.nav').forEach(x=>x.classList.toggle('active',x.dataset.view===activeView));document.querySelector('.mobile-nav')?.remove();let bar=document.createElement('div');bar.className='mobile-nav';[['dashboard','◫','Tổng quan'],['matches','▦','Trận'],['teams','♙','Đội'],['rankings','↗','Xếp hạng'],['settings','⚙','Khác']].forEach(([v,i,l])=>bar.innerHTML+=`<button data-view="${v}" class="${activeView===v?'active':''}"><span>${i}</span>${l}</button>`);document.body.appendChild(bar);bar.querySelectorAll('button').forEach(b=>b.onclick=()=>go(b.dataset.view));document.querySelectorAll('.sidebar .nav').forEach(b=>b.onclick=()=>go(b.dataset.view));}
function go(view){activeView=view;render()}
function render(){nav();let main=document.querySelector('#main');main.innerHTML=({dashboard:dashboard,matches:matchesPage,teams:teamsPage,rankings:rankingsPage,display:displayPage,settings:settingsPage,score:scorePage})[activeView]?.()||dashboard();bindCommon()}
function currentLive(){return db.matches.find(m=>m.status==='live')}
function dashboard(){let played=db.matches.filter(m=>['review','published','locked'].includes(m.status)).length;let live=currentLive();let ranks=getRankings();return `${pageHead('CONTROL DESK / OVERVIEW','Tổng quan giải đấu','Theo dõi trạng thái sân, tiến độ các trận và kết quả mới nhất.',`<button class="btn" data-action="backup">↓ Sao lưu</button><button class="btn primary" data-action="create-random">＋ Tạo lịch ngẫu nhiên</button>`)}
<div class="grid stats"><div class="card stat"><div class="label">ĐỘI ĐĂNG KÝ</div><div class="value accent">${db.teams.length}</div><div class="note">Đội trong danh sách giải</div></div><div class="card stat"><div class="label">SỐ TRẬN ĐÃ LẬP</div><div class="value">${db.matches.length}</div><div class="note">Mục tiêu ${db.settings.roundsPerTeam} trận / đội</div></div><div class="card stat"><div class="label">ĐÃ HOÀN TẤT</div><div class="value">${played}</div><div class="note">Chờ/đã xác nhận kết quả</div></div><div class="card stat"><div class="label">TRẠNG THÁI HỆ THỐNG</div><div class="value" style="font-size:17px;color:#a97716">LOCAL</div><div class="note">Chưa kết nối đồng bộ đám mây</div></div></div>
${live?liveCard(live):`<div class="match-feature"><div class="feature-top"><small>TRẬN TIẾP THEO · CONTROL DESK</small>${db.matches.length?statusTag(db.matches.find(m=>m.status==='scheduled')||db.matches[0]):'<span class="tag gray">Chưa có lịch</span>'}</div><h2>${db.matches.length?`Trận ${db.matches.find(m=>m.status==='scheduled')?.number||db.matches[0].number} · ${db.settings.roundName}`:'Chưa có trận đấu nào được lập'}</h2>${db.matches.length?allianceDisplay(db.matches.find(m=>m.status==='scheduled')||db.matches[0]):'<div class="score-callout">Nhập danh sách đội, chọn số trận mục tiêu rồi tạo lịch ngẫu nhiên.</div>'}</div>`}
<div class="split"><section class="card section-card">${cardTitle('Các trận gần đây','Kết quả và trạng thái mới nhất',`<button class="btn small" data-go="matches">Xem tất cả →</button>`)}${db.matches.length?`<div class="table-wrap"><table><thead><tr><th>TRẬN</th><th>LIÊN MINH</th><th>ĐIỂM TRẬN</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${db.matches.slice(0,5).map(m=>{let c=calc(m);return `<tr><td><b>${m.number}</b></td><td><span class="tag red">Đỏ</span> ${m.alliances.red.map(teamName).join(' · ')}<br><span class="tag blue">Xanh</span> ${m.alliances.blue.map(teamName).join(' · ')}</td><td class="badge-score">${fmt(c.matchTotal)}</td><td>${statusTag(m)}</td><td><button class="btn small" data-score="${m.id}">Mở</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Chưa có lịch trận. Hãy thêm đội và tạo lịch để bắt đầu.</div>'}</section>
<section class="card section-card">${cardTitle('Bảng xếp hạng tạm thời','Tính điểm đội sau phạt',`<button class="btn small" data-go="rankings">Chi tiết →</button>`)}${ranks.length?`<table><thead><tr><th>HẠNG</th><th>ĐỘI</th><th>ĐIỂM</th><th>TRẬN</th></tr></thead><tbody>${ranks.slice(0,5).map((x,i)=>`<tr><td>${String(i+1).padStart(2,'0')}</td><td><b>${x.name}</b></td><td class="badge-score">${fmt(x.total)}</td><td>${x.played}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Chưa có kết quả đã xác nhận.</div>'}</section></div>
<div class="banner info">Mỗi trận 4 đội cùng nhận điểm trận chung. Điểm phạt chỉ áp dụng cho đội vi phạm. Trang này hiện đang lưu dữ liệu trên trình duyệt của thiết bị.</div>`}
function liveCard(m){let c=calc(m);return `<div class="match-feature"><div class="feature-top"><small>TRẬN ĐANG DIỄN RA · SÂN ${m.field||'1'}</small><div class="timer-controls"><span id="clock" class="match-clock">${clockFmt(m.remaining??180)}</span><button class="btn small" data-timer="toggle" data-id="${m.id}">${m.timerRunning?'Tạm dừng':'Bắt đầu'}</button><button class="btn small" data-timer="reset" data-id="${m.id}">Đặt lại</button></div></div><h2>Trận ${m.number} · ${m.round||db.settings.roundName}</h2>${allianceDisplay(m)}<div class="score-callout"><span>ĐIỂM CHUNG TẠM TÍNH</span><b>${fmt(c.matchTotal)}</b><button class="btn small" data-score="${m.id}">Mở bảng chấm →</button></div></div>`}
function allianceDisplay(m){return `<div class="alliance-row"><div class="alliance redline"><div class="alliance-label">LIÊN MINH ĐỎ</div><div class="team-pair">${(m.alliances.red||[]).map(id=>`<span class="team-chip">${teamName(id)}</span>`).join('')||'<span class="team-chip">Chưa gán</span>'}</div></div><div class="versus">HỢP TÁC · 4 ĐỘI</div><div class="alliance blueline"><div class="alliance-label">LIÊN MINH XANH</div><div class="team-pair">${(m.alliances.blue||[]).map(id=>`<span class="team-chip">${teamName(id)}</span>`).join('')||'<span class="team-chip">Chưa gán</span>'}</div></div></div>`}
function teamsPage(){return `${pageHead('TOURNAMENT ROSTER','Danh sách đội','Nhập đội thủ công hoặc tải tệp CSV. Mỗi đội phải có mã duy nhất.',`<button class="btn" data-action="sample-teams">＋ Thêm đội mẫu</button><button class="btn primary" data-action="add-team">＋ Thêm đội</button>`)}
<div class="card section-card">${cardTitle('Nhập danh sách từ CSV','Định dạng cột: teamId,name,school (tên cột có thể có hoặc không).',`<label class="btn small file-input">↑ Chọn CSV<input id="csvInput" type="file" accept=".csv,text/csv" hidden></label>`)}<div class="banner info">Bạn có thể tải tệp danh sách đội từ Excel dưới dạng CSV UTF-8. Trước khi lưu, ứng dụng kiểm tra mã đội trùng và cho xem trước số lượng đội.</div></div>
<div class="card section-card" style="margin-top:14px">${cardTitle('Đội đã đăng ký',`${db.teams.length} đội · lịch mục tiêu ${db.settings.roundsPerTeam} trận mỗi đội`,`<input id="teamSearch" placeholder="Tìm mã hoặc tên đội…" style="padding:8px 10px;border:1px solid var(--line);border-radius:7px;font-size:10px">`)}${db.teams.length?`<div class="table-wrap"><table><thead><tr><th>MÃ ĐỘI</th><th>TÊN ĐỘI</th><th>TRƯỜNG</th><th>SỐ TRẬN ĐÃ LẬP</th><th></th></tr></thead><tbody id="teamRows">${db.teams.map(t=>`<tr data-teamrow="${(t.id+t.name+t.school).toLowerCase()}"><td><b>${t.id}</b></td><td>${t.name}</td><td>${t.school||'—'}</td><td>${db.matches.filter(m=>m.teams.includes(t.id)).length}</td><td><button class="btn small danger" data-delete-team="${t.id}">Xóa</button></td></tr>`).join('')}</tbody></table></div><div class="divider"></div><button class="btn small" data-action="export-teams">↓ Xuất danh sách CSV</button>`:'<div class="empty">Chưa có đội. Thêm thủ công hoặc tải danh sách CSV.</div>'}</div>`}
function matchesPage(){return `${pageHead('MATCH SCHEDULE','Lịch trận','Tạo lịch ngẫu nhiên theo số trận mục tiêu và xem trước phân bổ trước khi lưu.',`<button class="btn" data-action="export-matches">↓ Xuất lịch</button><button class="btn primary" data-action="create-random">＋ Tạo lịch ngẫu nhiên</button>`)}
<div class="grid stats"><div class="card stat"><div class="label">SỐ TRẬN MỤC TIÊU / ĐỘI</div><div class="value">${db.settings.roundsPerTeam}</div><div class="note">Có thể chỉnh trong Cài đặt</div></div><div class="card stat"><div class="label">TRẬN ĐÃ LẬP</div><div class="value">${db.matches.length}</div><div class="note">Mỗi trận gồm 4 đội</div></div><div class="card stat"><div class="label">LỊCH ĐÃ KHÓA</div><div class="value">${db.matches.filter(m=>m.status==='locked').length}</div><div class="note">Trận đã khóa không đổi đội</div></div><div class="card stat"><div class="label">VÒNG ĐẤU</div><div class="value" style="font-size:17px">${db.settings.roundName}</div><div class="note">Thiết lập trong phần cài đặt</div></div></div>
<div class="card section-card">${cardTitle('Danh sách trận','Bấm “Mở bảng chấm” để vào biểu mẫu nhập liệu.')}${db.matches.length?`<div class="table-wrap"><table><thead><tr><th>TRẬN</th><th>LIÊN MINH ĐỎ</th><th>LIÊN MINH XANH</th><th>ĐIỂM CHUNG</th><th>TRẠNG THÁI</th><th></th></tr></thead><tbody>${db.matches.map(m=>`<tr><td><b>${m.number}</b><div class="hint">${m.round||db.settings.roundName} · Sân ${m.field||'1'}</div></td><td>${(m.alliances.red||[]).map(id=>`<span class="team-mini">${teamName(id)}</span>`).join('')}</td><td>${(m.alliances.blue||[]).map(id=>`<span class="team-mini">${teamName(id)}</span>`).join('')}</td><td class="badge-score">${fmt(calc(m).matchTotal)}</td><td>${statusTag(m)}</td><td><button class="btn small" data-score="${m.id}">Mở bảng chấm</button> <button class="btn small" data-action="match-menu" data-id="${m.id}">•••</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Chưa có lịch. Cần tối thiểu 4 đội để tạo trận.</div>'}</div>`}
function scorePage(){let m=getMatch();if(!m){activeView='matches';return matchesPage()}attachScore(m);let c=calc(m);let err=validation(m);return `${pageHead(`SCORE ENTRY / MATCH ${m.number}`,`Trận ${m.number} · Bảng chấm điểm`,`${m.round||db.settings.roundName} · Sân ${m.field||'1'} · ${statusTag(m)}`,`<button class="btn" data-go="matches">← Lịch trận</button>`)}
<div class="match-feature"><div class="feature-top"><small>4 ĐỘI · 2 LIÊN MINH · 1 ĐIỂM TRẬN CHUNG</small><div class="timer-controls"><span id="clock" class="match-clock">${clockFmt(m.remaining??180)}</span><button class="btn small" data-timer="toggle" data-id="${m.id}">${m.timerRunning?'Tạm dừng':'Bắt đầu'}</button><button class="btn small" data-timer="reset" data-id="${m.id}">10s khởi động</button></div></div><h2>${m.round||db.settings.roundName} · Trận ${m.number}</h2>${allianceDisplay(m)}<div class="score-callout"><span>ĐIỂM TRẬN CHUNG</span><b>${fmt(c.matchTotal)}</b><span>· điểm đội sau phạt ở cuối trang</span></div></div>
<div class="grid" style="grid-template-columns:minmax(0,1.65fr) minmax(260px,.8fr);align-items:start"><section class="card section-card"><div class="score-tabs">${[['balls','Vật phẩm'],['flags','Cờ & núi'],['robots','Safe Zone'],['penalties','Lỗi & thẻ']].map(([v,l])=>`<button class="score-tab ${scoreTab===v?'active':''}" data-scoretab="${v}">${l}</button>`).join('')}</div><div id="scorePanel">${scorePanel(m)}</div><div class="divider"></div><div class="row" style="justify-content:space-between"><span class="hint">Tự động lưu bản nháp trên thiết bị này.</span><button class="btn primary" data-action="submit-score" data-id="${m.id}">Gửi chấm điểm →</button></div></section>
<aside class="card section-card">${cardTitle('Bảng điểm trực tiếp','Tính tự động theo luật hiện hành')}<div class="score-line"><span>Điểm Cháy</span><b>${fmt(c.components.fire||0)}</b></div><div class="score-line"><span>Mầm cây Rãnh 1</span><b>${fmt(c.components.seeds?.seed1||0)}</b></div><div class="score-line"><span>Mầm cây Rãnh 2</span><b>${fmt(c.components.seeds?.seed2||0)}</b></div><div class="score-line"><span>Mầm cây Rãnh 3</span><b>${fmt(c.components.seeds?.seed3||0)}</b></div><div class="score-line"><span>Cờ trên núi</span><b>${fmt(c.components.flags||0)}</b></div><div class="score-line"><span>Robot + thưởng liên minh</span><b>${fmt((c.components.robotPts||0)+(c.components.alliancePts||0))}</b></div><div class="score-line danger-text"><span>Bóng sai vị trí</span><b>${fmt(c.components.wrongPts||0)}</b></div><div class="total-box score-total" style="margin-top:12px"><small>ĐIỂM TRẬN CHUNG</small><strong>${fmt(c.matchTotal)}</strong></div><div class="divider"></div>${c.teams.map(x=>`<div class="score-line"><span>${teamName(x.id)} ${x.red?'<span class="tag red">Thẻ đỏ</span>':''}</span><b>${fmt(x.total)}</b></div>`).join('')}<div class="banner ${err.length?'':'info'}">${err.length?err.join(' · '):'Đang chấm nháp. Chưa hiển thị công khai cho đến khi xác nhận và công bố.'}</div><div class="row"><button class="btn small" data-action="confirm-score" data-id="${m.id}">✓ Xác nhận</button><button class="btn small" data-action="publish-score" data-id="${m.id}">Công bố</button><button class="btn small" data-action="lock-score" data-id="${m.id}">Khóa</button></div></aside></div>`}
function scorePanel(m){let s=m.score;
if(scoreTab==='balls')return `<div class="section-title"><div><h2>Nhập số vật phẩm hợp lệ</h2><p>Chấm theo trạng thái tại thời điểm 0:00. Bóng còn trên robot không tính.</p></div></div><div class="score-grid">${counterItem('Bóng cam trong Fire Zone',s.fire,'5 điểm / quả','fire')}${Object.entries(s.mountains).map(([mount,x])=>`<div class="score-item" style="grid-column:1/-1;background:#f9fbfe"><div><label><b>Núi ${mount}</b></label><small>Cây hợp lệ từng vị trí; bóng cam trên rãnh nhập ở sai vị trí</small></div><span class="tag green">4 rãnh</span></div>${counterItem(`Núi ${mount} · Mầm cây Rãnh 1`,x.seed1,'5 điểm / quả',`mount.${mount}.seed1`)}${counterItem(`Núi ${mount} · Tầng trang trí`,x.decor,'Tính như Rãnh 1 · 5 điểm',`mount.${mount}.decor`)}${counterItem(`Núi ${mount} · Mầm cây Rãnh 2`,x.seed2,'10 điểm / quả',`mount.${mount}.seed2`)}${counterItem(`Núi ${mount} · Mầm cây Rãnh 3`,x.seed3,'15 điểm / quả',`mount.${mount}.seed3`)}${counterItem(`Núi ${mount} · Bóng cam sai vị trí`,x.wrong,'−3 điểm / quả',`mount.${mount}.wrong`)}`).join('')}</div><div class="banner info">Bóng chạm vạch được tính. Tầng trang trí tính điểm như Rãnh 1. Bóng xanh trong Fire Zone nhập ở mục “Lỗi & thẻ” → bóng sai vị trí.</div>`;
if(scoreTab==='flags')return `<div class="section-title"><div><h2>Trạng thái cờ tại mỗi ngọn núi</h2><p>Ứng dụng tự tính cờ phủ xanh: đủ ít nhất 1 cây ở Rãnh 1, 2 và 3.</p></div></div><div class="score-grid">${Object.entries(s.mountains).map(([mount,x])=>{let cover=(+x.seed1||0)+(+x.decor||0)>0&&(+x.seed2||0)>0&&(+x.seed3||0)>0;return `<div class="card section-card"><div class="section-title"><h2>Núi ${mount}</h2><span class="tag ${x.flag?'green':'gray'}">${x.flag?(cover?'40 điểm':'20 điểm'):'Chưa cắm'}</span></div><label class="radio-pill"><input type="checkbox" data-bind="mount.${mount}.flag" ${x.flag?'checked':''}> Cờ cắm vững, nghiêng không quá 45°</label><div class="hint">${cover?'Đủ cây ở cả ba rãnh: áp dụng 40 điểm tổng.':'Cờ hợp lệ: 20 điểm; nếu đủ cây cả 3 rãnh, tự nâng lên 40.'}</div></div>`}).join('')}</div><div class="banner">Luật nguồn có ví dụ tổng 299 điểm nhưng cộng hạng mục nêu ra được 269. App tính theo từng hạng mục, không dùng tổng mẫu làm công thức.</div>`;
if(scoreTab==='robots')return `<div class="section-title"><div><h2>Chấm đỗ Safe Zone ở thời điểm 0:00</h2><p>Chỉ vùng của liên minh mình được ghi điểm.</p></div></div><div class="score-grid">${m.teams.map(id=>`<div class="card section-card"><div class="section-title"><h2>${teamName(id)}</h2><span class="tag ${m.alliances.red.includes(id)?'red':'blue'}">${m.alliances.red.includes(id)?'ĐỎ':'XANH'}</span></div><div class="field"><label>Trạng thái robot</label><select data-bind="robots.${id}"><option value="none" ${!s.robots[id]||s.robots[id]==='none'?'selected':''}>Không vào Safe Zone · 0</option><option value="partial" ${s.robots[id]==='partial'?'selected':''}>Đỗ một phần trong vùng mình · 5</option><option value="full" ${s.robots[id]==='full'?'selected':''}>Đỗ toàn phần trong vùng mình · 10</option><option value="opponent" ${s.robots[id]==='opponent'?'selected':''}>Đỗ trong vùng đối phương · 0</option></select></div></div>`).join('')}</div><div class="banner info">Thưởng +10 được tự động cộng khi cả hai robot cùng một liên minh đỗ toàn phần trong Safe Zone của chính liên minh đó.</div>`;
return `<div class="section-title"><div><h2>Lỗi, bóng xanh sai vị trí và thẻ theo từng đội</h2><p>Mỗi penalty −5; mỗi thẻ vàng −10; hai thẻ vàng thành thẻ đỏ.</p></div><button class="btn small" data-action="add-penalty" data-id="${m.id}">＋ Thêm sự kiện</button></div><div class="score-grid">${counterItem('Bóng xanh trong Fire Zone',s.wrongGreen||0,'−3 điểm / quả vào điểm chung','wrongGreen')}</div><div class="divider"></div>${m.teams.map(id=>{let ev=(m.penalties||[]).filter(x=>x.teamId===id);return `<div class="card section-card" style="margin-bottom:10px"><div class="section-title"><h2>${teamName(id)}</h2><span>${ev.map(x=>`<span class="tag ${x.type==='red'?'red':x.type==='yellow'?'yellow':'gray'}">${x.type==='penalty'?'Penalty':x.type==='yellow'?'Thẻ vàng':x.type==='red'?'Thẻ đỏ':'Cảnh cáo'} ×${x.count}</span>`).join(' ')||'<span class="tag green">Chưa ghi nhận lỗi</span>'}</span></div><button class="btn small" data-action="add-penalty-team" data-id="${m.id}" data-team="${id}">＋ Ghi nhận cho đội này</button>${ev.length?`<button class="btn small danger" data-action="clear-penalties" data-id="${m.id}" data-team="${id}">Xóa sự kiện</button>`:''}</div>`}).join('')}<div class="field full"><label>Ghi chú trọng tài</label><textarea data-bind="notes" rows="3" placeholder="Ghi chú tình huống cần lưu lại">${esc(s.notes||'')}</textarea></div>`;
}
function counterItem(label,val,sub,path){return `<div class="score-item"><div><label>${label}</label><small>${sub}</small></div><div class="counter"><button data-counter="${path}" data-delta="-1">−</button><input type="number" min="0" value="${+val||0}" data-counter-input="${path}"><button data-counter="${path}" data-delta="1">＋</button></div></div>`}
function rankingsPage(){let r=getRankings();return `${pageHead('RANKING TABLE','Bảng xếp hạng','Điểm đội sau phạt riêng. Hòa điểm: điểm trận cao nhất, sau đó tổng điểm phạt thấp hơn.',`<button class="btn" data-action="export-rankings">↓ Xuất CSV</button>`)}<div class="banner info">Ở vòng xếp hạng, các đội không thi đấu đối kháng. Đây là bảng tổng điểm cá nhân từng đội qua các trận, không phải thắng/thua liên minh.</div><div class="card section-card">${cardTitle('Xếp hạng tạm thời',`Tính từ ${db.matches.filter(m=>m.status==='published'||m.status==='locked').length} trận đã công bố hoặc khóa.`)}${r.length?`<div class="table-wrap"><table><thead><tr><th>HẠNG</th><th>MÃ ĐỘI</th><th>TÊN ĐỘI</th><th>TRẬN TÍNH</th><th>ĐIỂM XẾP HẠNG</th><th>ĐIỂM CAO NHẤT</th><th>ĐIỂM PHẠT</th></tr></thead><tbody>${r.map((x,i)=>`<tr><td><b>${String(i+1).padStart(2,'0')}</b></td><td>${x.id}</td><td>${x.name}</td><td>${x.played}/${db.settings.roundsPerTeam}</td><td class="badge-score">${fmt(x.total)}</td><td>${fmt(x.highest)}</td><td>${fmt(x.penalties)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Bảng xếp hạng sẽ hiện khi có kết quả được công bố.</div>'}</div>`}
function getRankings(){let published=db.matches.filter(m=>['published','locked'].includes(m.status));let counts=Object.fromEntries(db.teams.map(t=>[t.id,published.filter(m=>m.teams.includes(t.id)).length]));let nonzero=Object.values(counts).filter(n=>n>0);let min=nonzero.length?Math.min(...nonzero):0;return db.teams.map(t=>{let games=published.filter(m=>m.teams.includes(t.id)).map(m=>({total:calc(m).teams.find(x=>x.id===t.id)?.total||0,highest:calc(m).matchTotal,penalties:calc(m).teams.find(x=>x.id===t.id)?.penaltyPoints||0})).sort((a,b)=>a.total-b.total);let kept=games.slice(Math.max(0,games.length-min));return {id:t.id,name:t.name,played:kept.length,total:kept.reduce((a,x)=>a+x.total,0),highest:games.length?Math.max(...games.map(x=>x.highest)):0,penalties:games.reduce((a,x)=>a+x.penalties,0)}}).sort((a,b)=>b.total-a.total||b.highest-a.highest||a.penalties-b.penalties)}
function displayPage(){let m=getMatch(db.projectedMatch)||db.matches.find(x=>x.status==='live')||db.matches.find(x=>x.status==='published')||db.matches[0];return `${pageHead('SPECTATOR VIEW','Màn hình khán giả','Chọn trận cần chiếu. Chỉ trận đã công bố mới được xem công khai.',`<button class="btn" data-action="copy-url">⧉ Sao chép link xem</button>`)}<div class="card section-card"><div class="filter-row"><label style="font-size:10px;font-weight:700">Trận đang chiếu:</label><select id="projectMatch"><option value="">Chưa chọn</option>${db.matches.map(x=>`<option value="${x.id}" ${m?.id===x.id?'selected':''}>Trận ${x.number} · ${x.round||db.settings.roundName} · ${x.status==='published'?'Đã công bố':x.status==='locked'?'Đã khóa':'Chưa công bố'}</option>`).join('')}</select><span class="hint">Lựa chọn này không đổi trận đang chấm ở bàn điều hành.</span></div>${m?`<div class="public-board"><h2>FAnRoC 2026 · ${m.round||db.settings.roundName.toUpperCase()} · TRẬN ${m.number}</h2><div class="public-score">${['published','locked'].includes(m.status)?fmt(calc(m).matchTotal):'—'}</div><div style="color:#9db3d0;font-size:10px">ĐIỂM TRẬN CHUNG · ${['published','locked'].includes(m.status)?'KẾT QUẢ ĐÃ CÔNG BỐ':'CHƯA CÔNG BỐ'}</div><div class="public-details" style="margin-top:20px"><div class="public-team"><span class="tag red">LIÊN MINH ĐỎ</span><p>${m.alliances.red.map(teamName).join(' · ')}</p>${['published','locked'].includes(m.status)?m.alliances.red.map(id=>`<small>${teamName(id)}: ${fmt(calc(m).teams.find(x=>x.id===id)?.total||0)} điểm</small><br>`).join(''):''}</div><div class="public-team"><span class="tag blue">LIÊN MINH XANH</span><p>${m.alliances.blue.map(teamName).join(' · ')}</p>${['published','locked'].includes(m.status)?m.alliances.blue.map(id=>`<small>${teamName(id)}: ${fmt(calc(m).teams.find(x=>x.id===id)?.total||0)} điểm</small><br>`).join(''):''}</div></div></div>`:'<div class="empty">Chưa có trận để hiển thị.</div>'}</div><div class="banner info">Để dùng màn hình này, mở mục “Màn hình khán giả” trên máy chiếu. Trang xem bên ngoài thiết bị chỉ hoạt động khi bật backend đồng bộ.</div>`}
function settingsPage(){return `${pageHead('EVENT CONFIGURATION','Cài đặt & sao lưu','Cấu hình lịch đấu, luật và phương án bảo toàn dữ liệu.',`<button class="btn" data-action="restore">↑ Khôi phục</button><button class="btn primary" data-action="backup">↓ Tạo bản sao lưu</button>`)}<div class="split"><section class="card section-card">${cardTitle('Cấu hình vòng đấu','Áp dụng cho lịch tạo mới')}<div class="form-grid"><div class="field"><label>Tên giải</label><input id="setTournament" value="${esc(db.settings.tournament)}"></div><div class="field"><label>Vòng đấu</label><select id="setRound"><option ${db.settings.roundName==='Vòng xếp hạng'?'selected':''}>Vòng xếp hạng</option><option ${db.settings.roundName==='Bán kết'?'selected':''}>Bán kết</option><option ${db.settings.roundName==='Chung kết'?'selected':''}>Chung kết</option></select></div><div class="field"><label>Số trận mục tiêu / đội</label><input id="setRounds" type="number" min="1" max="20" value="${db.settings.roundsPerTeam}"><div class="hint">Hệ thống sẽ cố gắng cân bằng số trận từng đội.</div></div><div class="field"><label>Tiền tố mã đội mới</label><input id="setPrefix" value="${esc(db.settings.teamPrefix)}"></div></div><div class="divider"></div><button class="btn primary" data-action="save-settings">Lưu cấu hình</button></section>
<section class="card section-card">${cardTitle('Sao lưu và khôi phục','Bản sao lưu JSON bao gồm đội, lịch, điểm và nhật ký cục bộ.')}<div class="banner">Hiện tại, dữ liệu chỉ nằm trong trình duyệt trên thiết bị này. Sao lưu thủ công thường xuyên. Tự động sao lưu lên đám mây và đồng bộ đa thiết bị cần hoàn tất kết nối backend.</div><div class="quick-actions"><button class="btn primary" data-action="backup">Tạo / tải bản sao lưu JSON</button><label class="btn">Chọn tệp khôi phục<input id="restoreFile" type="file" accept=".json,application/json" hidden></label></div><p class="foot-note">Khi khôi phục, dữ liệu hiện có trên thiết bị sẽ được thay bằng bản sao lưu đã chọn. Hãy tải bản sao lưu hiện tại trước khi phục hồi. Tệp xuất là dữ liệu nhạy cảm của giải, chỉ chia sẻ với người được phân quyền.</p></section></div>
<div class="card section-card" style="margin-top:15px">${cardTitle('Kiểm tra công thức điểm','Chạy các ca mẫu cục bộ để đối chiếu cách tính.') }<div class="row"><button class="btn" data-action="run-cases">Chạy kiểm tra nhanh</button><span id="caseResult" class="hint"></span></div></div>
<div class="banner info">Chốt với Ban Tổ chức: luật ghi ví dụ 299 điểm, nhưng cộng hạng mục minh họa được 269. App dùng công thức từng hạng mục; không hard-code tổng ví dụ này.</div>`}
function validation(m){let a=[];if(m.teams.length!==4)a.push('Cần đủ 4 đội');let dup=m.teams.length!==new Set(m.teams).size;if(dup)a.push('Có đội bị lặp');return a}
function addTeam(name,id,school){id=(id||'').trim();name=(name||'').trim();if(!id||!name)throw Error('Cần nhập mã đội và tên đội.');if(db.teams.some(t=>t.id.toLowerCase()===id.toLowerCase()))throw Error('Mã đội đã tồn tại: '+id);db.teams.push({id,name,school:(school||'').trim()});save()}
function modal(content){document.querySelector('#modalBody').innerHTML=`<div class="modal-inner">${content}</div>`;document.querySelector('#modal').showModal();bindModal()}
function addTeamModal(){modal(`<div class="modal-head"><h2>Thêm đội tham gia</h2><button class="close" data-close>×</button></div><form id="teamForm" class="form-grid"><div class="field"><label>Mã đội</label><input name="id" placeholder="Ví dụ FTC25209" required></div><div class="field"><label>Tên đội</label><input name="name" placeholder="Tên hiển thị" required></div><div class="field full"><label>Trường / đơn vị</label><input name="school" placeholder="Không bắt buộc"></div><div class="field full row"><button class="btn primary">Lưu đội</button><button type="button" class="btn" data-close>Hủy</button></div></form>`)}
function createRandom(){
 if(db.teams.length<4){notify('Cần ít nhất 4 đội để tạo lịch.');return}
 let goal=Math.max(1,Math.min(20,+db.settings.roundsPerTeam||4));
 // Replace only unstarted schedule rows; preserve all games already underway, scored, published or locked.
 db.matches=db.matches.filter(m=>m.status!=='scheduled');
 let counts=Object.fromEntries(db.teams.map(t=>[t.id,db.matches.filter(m=>m.teams.includes(t.id)).length]));
 let pairAlliance={};db.matches.forEach(m=>[m.alliances.red,m.alliances.blue].forEach(pair=>{let k=pair.slice().sort().join('|');pairAlliance[k]=(pairAlliance[k]||0)+1}));
 let deficits=db.teams.reduce((a,t)=>a+Math.max(0,goal-counts[t.id]),0);let maxGames=Math.floor(deficits/4);let games=[];
 for(let g=0;g<maxGames;g++){
  let pool=db.teams.filter(t=>counts[t.id]<goal);if(pool.length<4)break;
  let best=null,bestCost=Infinity;
  for(let attempt=0;attempt<600;attempt++){
   let cand=pool.slice().sort(()=>Math.random()-.5).slice(0,4);let [a,b,c,d]=cand;
   for(let v of [[a,b,c,d],[a,c,b,d],[a,d,b,c]]){
    let [r1,r2,b1,b2]=v;let redKey=[r1.id,r2.id].sort().join('|'),blueKey=[b1.id,b2.id].sort().join('|');
    let cost=v.reduce((s,t)=>s+counts[t.id]*20,0)+(pairAlliance[redKey]||0)*80+(pairAlliance[blueKey]||0)*80;
    if(cost<bestCost){bestCost=cost;best={red:[r1,r2],blue:[b1,b2]}}
   }
  }
  if(!best)break;let teams=[...best.red,...best.blue].map(t=>t.id);teams.forEach(id=>counts[id]++);[best.red,best.blue].forEach(pair=>{let k=pair.map(t=>t.id).sort().join('|');pairAlliance[k]=(pairAlliance[k]||0)+1});games.push({teams,alliances:{red:best.red.map(t=>t.id),blue:best.blue.map(t=>t.id)}})
 }
 let maxNum=Math.max(0,...db.matches.map(m=>+m.number||0))+1;
 let preview=Object.entries(counts).map(([id,n])=>`${id}: ${n} trận${n<goal?' · thiếu '+(goal-n):''}`).join('<br>');
 let remainder=deficits%4;
 modal(`<div class="modal-head"><h2>Xem trước lịch ngẫu nhiên</h2><button class="close" data-close>×</button></div><div class="banner info">Tạo ${games.length} trận mới · mục tiêu ${goal} trận/đội. Đã giữ nguyên mọi trận bắt đầu, đã chấm hoặc khóa.${remainder?` Còn ${remainder} lượt đội chưa ghép được thành một trận 4 đội.`:''}</div><div class="card section-card" style="max-height:250px;overflow:auto;font-size:10px;line-height:1.8">${preview}</div><p class="foot-note">Thuật toán cân bằng số trận và hạn chế các cặp cùng liên minh lặp lại; lịch vẫn cần được Ban Tổ chức rà soát trước khi công bố.</p><div class="row"><button class="btn primary" id="confirmSchedule">Tạo ${games.length} trận</button><button class="btn" data-close>Hủy</button></div>`);
 document.querySelector('#confirmSchedule').onclick=()=>{for(let i=0;i<games.length;i++){let pair=games[i],m={id:uid('match'),number:maxNum+i,round:db.settings.roundName,field:'1',teams:pair.teams,alliances:pair.alliances,status:'scheduled',remaining:180,score:null,penalties:[]};attachScore(m);db.matches.push(m)}save();document.querySelector('#modal').close();go('matches');notify(`Đã tạo ${games.length} trận. Rà soát phân bổ trước khi dùng.`)}
}
function exportCSV(filename,rows){let csv=rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n');download('\ufeff'+csv,filename,'text/csv;charset=utf-8')}
function download(data,name,type){let b=new Blob([data],{type}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
function backup(){let obj={schemaVersion:1,exportedAt:new Date().toISOString(),data:db};download(JSON.stringify(obj,null,2),`fanroc-backup-${new Date().toISOString().slice(0,10)}.json`,'application/json');notify('Đã tải bản sao lưu JSON.')}
function restoreFile(file){let r=new FileReader();r.onload=()=>{try{let o=JSON.parse(r.result);let data=o.data||o;if(!data.teams||!data.matches)throw Error('Tệp không có cấu trúc dữ liệu FAnRoC.');db={...structuredClone(initial),...data};save();render();notify('Đã khôi phục dữ liệu từ bản sao lưu.')}catch(e){notify(e.message||'Không đọc được tệp.')}};r.readAsText(file)}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function clockFmt(s){s=Math.max(0,+s||0);return `${Math.floor(s/60)}:${String(s%60).padStart(2,'0')}`}
function timerUpdate(id){let m=getMatch(id);if(!m)return;m.remaining=Math.max(0,(m.remaining??180)-1);if(m.remaining===0){m.timerRunning=false;m.status='review';save();render();notify('Hết giờ · chuyển sang chờ chấm kết quả');return}save();let el=document.querySelector('#clock');if(el)el.textContent=clockFmt(m.remaining)}
let timerInterval;
function startTimer(m){clearInterval(timerInterval);m.timerRunning=true;m.timerStamp=Date.now();if(m.remaining==null)m.remaining=180;timerInterval=setInterval(()=>{let elapsed=Math.floor((Date.now()-m.timerStamp)/1000);if(elapsed>0){m.remaining=Math.max(0,m.remaining-elapsed);m.timerStamp=Date.now();save();let el=document.querySelector('#clock');if(el)el.textContent=clockFmt(m.remaining);if(m.remaining<=30)el?.classList.add('danger-text');if(m.remaining===0){clearInterval(timerInterval);m.timerRunning=false;m.status='review';save();render();notify('Hết giờ · trận chuyển sang chờ chấm')}}},300)}
function bindCommon(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-score]').forEach(b=>b.onclick=()=>{db.selectedMatch=b.dataset.score;scoreTab='balls';go('score')});document.querySelectorAll('[data-scoretab]').forEach(b=>b.onclick=()=>{scoreTab=b.dataset.scoretab;render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id,b.dataset.team));document.querySelectorAll('[data-timer]').forEach(b=>b.onclick=()=>{let m=getMatch(b.dataset.id);if(!m)return;if(b.dataset.timer==='reset'){clearInterval(timerInterval);m.remaining=180;m.timerRunning=false;save();render();return}if(m.timerRunning){clearInterval(timerInterval);m.timerRunning=false;save();render()}else{m.status='live';if(!m.remaining)m.remaining=180;startTimer(m);save();render()}});
document.querySelectorAll('[data-bind]').forEach(el=>{let p=el.dataset.bind;let apply=()=>{let m=getMatch();if(!m)return;let val=el.type==='checkbox'?el.checked:el.value;setPath(m.score,p,val);save();refreshScoreAside()};el.onchange=apply;if(el.tagName==='TEXTAREA')el.oninput=apply});document.querySelectorAll('[data-counter]').forEach(b=>b.onclick=()=>counter(b.dataset.counter,+b.dataset.delta));document.querySelectorAll('[data-counter-input]').forEach(el=>el.onchange=()=>setScoreValue(el.dataset.counterInput,Math.max(0,+el.value||0)));document.querySelectorAll('[data-delete-team]').forEach(b=>b.onclick=()=>deleteTeam(b.dataset.deleteTeam));let search=document.querySelector('#teamSearch');if(search)search.oninput=()=>document.querySelectorAll('[data-teamrow]').forEach(r=>r.style.display=r.dataset.teamrow.includes(search.value.toLowerCase())?'':'none');let csv=document.querySelector('#csvInput');if(csv)csv.onchange=e=>importTeams(e.target.files[0]);let pm=document.querySelector('#projectMatch');if(pm)pm.onchange=()=>{db.projectedMatch=pm.value;save();render()};let rest=document.querySelector('#restoreFile');if(rest)rest.onchange=e=>e.target.files[0]&&restoreFile(e.target.files[0]);}
function refreshScoreAside(){let m=getMatch();if(m){save();render()}}
function counter(path,delta){let m=getMatch();if(!m)return;let old=+getPath(m.score,path)||0;setPath(m.score,path,Math.max(0,old+delta));save();render()}
function setScoreValue(path,v){let m=getMatch();if(!m)return;setPath(m.score,path,v);save();render()}
function setPath(obj,path,v){let keys=path.split('.');let cur=obj;for(let i=0;i<keys.length-1;i++)cur=cur[keys[i]]??(cur[keys[i]]={});cur[keys.at(-1)]=v}
function getPath(obj,path){return path.split('.').reduce((o,k)=>o?.[k],obj)}
function action(type,id,team){let m=getMatch(id);switch(type){case'add-team':addTeamModal();break;case'sample-teams':[['FR25209','FRITS 25209','THPT FPT Hà Nội'],['FR25110','Cyan Sparks','THPT FPT Hà Nội'],['ROBO06','Robo Rangers','THCS mẫu'],['GREEN01','Green Phoenix','THCS mẫu'],['FIRE02','Firefly Robotics','THCS mẫu'],['SEED03','Seed Makers','THCS mẫu'],['FOREST4','Forest Bots','THCS mẫu'],['NORTH05','North Star','THCS mẫu']].forEach(x=>{try{addTeam(x[1],x[0],x[2])}catch{}});render();notify('Đã thêm dữ liệu đội mẫu để thử.');break;case'create-random':createRandom();break;case'backup':backup();break;case'restore':document.querySelector('#restoreFile')?.click();break;case'export-teams':exportCSV('fanroc-teams.csv',[['teamId','name','school'],...db.teams.map(t=>[t.id,t.name,t.school])]);break;case'export-matches':exportCSV('fanroc-matches.csv',[['match','round','field','red1','red2','blue1','blue2','status','shared_score'],...db.matches.map(m=>[m.number,m.round,m.field,...m.alliances.red.map(teamName),...m.alliances.blue.map(teamName),m.status,calc(m).matchTotal])]);break;case'export-rankings':{let r=getRankings();exportCSV('fanroc-rankings.csv',[['rank','teamId','name','matches','ranking_score','highest_match','penalties'],...r.map((x,i)=>[i+1,x.id,x.name,x.played,x.total,x.highest,x.penalties])]);break}case'save-settings':db.settings.tournament=document.querySelector('#setTournament').value;db.settings.roundName=document.querySelector('#setRound').value;db.settings.roundsPerTeam=Math.max(1,+document.querySelector('#setRounds').value||4);db.settings.teamPrefix=document.querySelector('#setPrefix').value;save();render();notify('Đã lưu cấu hình.');break;case'submit-score':if(validation(m).length){notify(validation(m).join('. '));break}m.status='review';save();render();notify('Đã gửi kết quả chờ xác nhận.');break;case'confirm-score':if(m){m.status='review';m.confirmedAt=new Date().toISOString();save();render();notify('Đã xác nhận kết quả.')}break;case'publish-score':if(m){if(!m.confirmedAt){notify('Cần xác nhận kết quả trước khi công bố.');break}m.status='published';save();render();notify('Kết quả đã công bố.')}break;case'lock-score':if(m){m.status='locked';m.timerRunning=false;clearInterval(timerInterval);save();render();notify('Đã khóa biên bản.')}break;case'add-penalty':case'add-penalty-team':penaltyModal(m,team);break;case'clear-penalties':if(m){m.penalties=m.penalties.filter(x=>x.teamId!==team);save();render()}break;case'match-menu':matchMenu(m);break;case'export-teams':break;case'run-cases':runCases();break;case'copy-url':navigator.clipboard?.writeText(location.href).then(()=>notify('Đã sao chép đường dẫn.')).catch(()=>notify('Sao chép đường dẫn trên thanh địa chỉ.'));break;}}
function penaltyModal(m,teamId){if(!m)return;let opts=m.teams.map(id=>`<option value="${id}" ${teamId===id?'selected':''}>${teamName(id)}</option>`).join('');modal(`<div class="modal-head"><h2>Ghi nhận lỗi / thẻ</h2><button class="close" data-close>×</button></div><form id="penForm" class="form-grid"><div class="field full"><label>Đội vi phạm</label><select name="teamId">${opts}</select></div><div class="field"><label>Mức xử lý</label><select name="type"><option value="penalty">Penalty · −5 điểm</option><option value="yellow">Thẻ vàng · −10 điểm</option><option value="red">Thẻ đỏ · đội nhận 0 điểm</option><option value="warning">Cảnh cáo · không trừ điểm</option></select></div><div class="field"><label>Số lượng</label><input name="count" type="number" min="1" value="1"></div><div class="field full"><label>Ghi chú / mã luật</label><input name="note" placeholder="Không bắt buộc"></div><div class="field full"><button class="btn primary">Lưu sự kiện</button></div></form>`);document.querySelector('#penForm').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),count=Math.max(1,+f.get('count')||1);m.penalties.push({id:uid('pen'),teamId:f.get('teamId'),type:f.get('type'),count,note:f.get('note'),time:new Date().toISOString()});save();document.querySelector('#modal').close();render();notify('Đã ghi nhận sự kiện.')};}
function bindModal(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>document.querySelector('#modal').close());let tf=document.querySelector('#teamForm');if(tf)tf.onsubmit=e=>{e.preventDefault();let f=new FormData(tf);try{addTeam(f.get('name'),f.get('id'),f.get('school'));document.querySelector('#modal').close();render();notify('Đã thêm đội.')}catch(err){notify(err.message)}}}
function matchMenu(m){if(!m)return;let lock=['live','published','locked','review'].includes(m.status);modal(`<div class="modal-head"><h2>Trận ${m.number} · Tùy chọn</h2><button class="close" data-close>×</button></div><div class="quick-actions"><button class="btn" id="cloneMatch">Nhân bản trận</button><button class="btn" id="projectThis">Chiếu trận này</button><button class="btn ${lock?'danger':''}" id="deleteMatch">${lock?'Không thể xóa trận đã bắt đầu':'Xóa trận'}</button></div><p class="foot-note">Trận đã diễn ra/được công bố/khóa sẽ không bị xóa khi tạo lại lịch.</p>`);document.querySelector('#projectThis').onclick=()=>{db.projectedMatch=m.id;save();document.querySelector('#modal').close();go('display')};document.querySelector('#cloneMatch').onclick=()=>{let cp=structuredClone(m);cp.id=uid('match');cp.number=Math.max(0,...db.matches.map(x=>+x.number||0))+1;cp.status='scheduled';cp.score=null;cp.penalties=[];cp.remaining=180;attachScore(cp);db.matches.push(cp);save();document.querySelector('#modal').close();render();notify('Đã nhân bản trận.')};document.querySelector('#deleteMatch').onclick=()=>{if(lock){notify('Trận đã bắt đầu/được xác nhận không thể xóa.');return}db.matches=db.matches.filter(x=>x.id!==m.id);save();document.querySelector('#modal').close();render();notify('Đã xóa trận.')};}
function importTeams(file){if(!file)return;let fr=new FileReader();fr.onload=()=>{let lines=String(fr.result).split(/\r?\n/).filter(x=>x.trim());if(!lines.length)return;let parse=line=>line.split(/,(?=(?:[^"]*"[^"]*")*[^"]*$)/).map(x=>x.trim().replace(/^"|"$/g,'').replaceAll('""','"'));let rows=lines.map(parse);if(/team.?id|mã đội/i.test(rows[0][0]))rows.shift();let ok=0,errors=[];rows.forEach((r,i)=>{try{addTeam(r[1]||r[0],r[0],r[2]);ok++}catch(e){errors.push(`dòng ${i+1}: ${e.message}`)}});render();modal(`<div class="modal-head"><h2>Kết quả nhập CSV</h2><button class="close" data-close>×</button></div><p>Đã thêm <b>${ok}</b> đội.</p>${errors.length?`<div class="banner">${errors.slice(0,8).map(esc).join('<br>')}</div>`:'<div class="banner info">Không có lỗi. Danh sách đã được lưu trên thiết bị này.</div>'}<button class="btn primary" data-close>Đóng</button>`)};fr.readAsText(file,'UTF-8')}
function deleteTeam(id){if(db.matches.some(m=>m.teams.includes(id))){notify('Đội đã được gán vào lịch. Xóa lịch trước hoặc giữ đội trong danh sách.');return}db.teams=db.teams.filter(t=>t.id!==id);save();render();notify('Đã xóa đội.')}
function runCases(){let m={teams:['a','b','c','d'],alliances:{red:['a','b'],blue:['c','d']},score:{fire:12,mountains:{A:{seed1:10,decor:0,seed2:4,seed3:0,wrong:0,flag:false},B:{seed1:0,decor:0,seed2:0,seed3:0,wrong:0,flag:false},C:{seed1:0,decor:0,seed2:0,seed3:0,wrong:0,flag:false},D:{seed1:0,decor:0,seed2:0,seed3:0,wrong:0,flag:false}},robots:{a:'full',b:'none',c:'partial',d:'none'},penalties:[]}};let result=calc(m).matchTotal,el=document.querySelector('#caseResult');el.textContent=result===175?'✓ Ca mẫu cơ bản đạt 175 điểm.':'✗ Sai lệch ca mẫu: '+result;el.className=result===175?'good-text':'danger-text'}
document.querySelector('#helpBtn').onclick=()=>modal(`<div class="modal-head"><h2>Hướng dẫn nhanh</h2><button class="close" data-close>×</button></div><ol style="font-size:11px;line-height:1.8"><li>Nhập đội ở mục <b>Danh sách đội</b> (có thể tải CSV).</li><li>Chọn số trận mục tiêu trong <b>Cài đặt & sao lưu</b>.</li><li>Dùng <b>Tạo lịch ngẫu nhiên</b>, xem số trận phân bổ rồi xác nhận.</li><li>Mở bảng chấm ở từng trận; nhập vật phẩm, cờ, Safe Zone và lỗi.</li><li>Gửi chấm điểm → xác nhận → công bố. Tạo bản sao lưu JSON thường xuyên.</li></ol><div class="banner">Bản hiện tại lưu trên thiết bị trình duyệt. Muốn nhiều máy đồng bộ và backup tự động, cần cấu hình backend theo hướng dẫn đi kèm.</div>`);
if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
render();
